Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:13px;margin-bottom:2px;">Convolutional network pipeline</div>

<label style="gap:4px;">
  <span>Step through the network</span>
  <button id="btnStage">Stage 1/4 — RGB input</button>
</label>

<label style="gap:4px;">
  <span>Output channel of layer 1: <b id="chOut">1</b> of 5</span>
  <input type="range" id="chSel" min="1" max="5" step="1" value="1">
</label>

<label style="gap:4px;">
  <span>Emphasize</span>
  <span style="display:flex;gap:4px;flex-wrap:wrap;">
    <button id="roleAct">Activations</button>
    <button id="roleFilt">Filters</button>
    <button id="roleBoth" class="active">Both</button>
  </span>
</label>

<div style="border-top:1px solid #dcdfe3;margin-top:6px;padding-top:6px;font-weight:700;">Guided demo</div>
<div style="display:flex;gap:4px;">
  <button id="demoPrev">◀ Prev</button>
  <button id="demoNext">Next ▶</button>
</div>
<div id="demoTitle" style="font-weight:700;margin-top:2px;">1. RGB input</div>
<div id="demoText" style="line-height:1.4;">The input is a W×H image with 3 channels — three large pink sheets labelled R, G, B.</div>

<div style="border-top:1px solid #dcdfe3;margin-top:6px;padding-top:6px;color:#555;line-height:1.4;">
  Drag to orbit: the stacks are real 3D tensors — “channels” is a depth axis perpendicular to the W×H image plane.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
   input sheet (×3)      → BoxGeometry(3.2,0.06,3.2)  pink  + EdgesGeometry black
   layer1 map (×5)       → BoxGeometry(1.8,0.06,1.8)  pink  + edges
   logit diamond (×9)    → BoxGeometry(0.4,0.05,0.4)  pink  + edges
   layer1 filter (5×3)   → BoxGeometry(0.8,0.05,0.8)  blue  + edges
   layer2 filter (2×5)   → BoxGeometry(0.8,0.05,0.8)  blue  + edges
   arrow shaft           → CylinderGeometry r=0.045   black
   arrow head            → ConeGeometry(0.13,0.30)    black
   title rule / caption  → CylinderGeometry r=0.030   black
   channel bracket       → 4 × CylinderGeometry r=0.030 (serifs + broken stem)
   curly brace           → TubeGeometry on CatmullRomCurve3  r=0.035
   dashed leader         → dashed chain of CylinderGeometry on QuadraticBezierCurve3
   ellipsis dot          → SphereGeometry(0.085)      black
   all text              → addLabel() HTML overlay, serif (monospace for 'heron')
   ────────────────────────────────────────────────────────────────────────── */

const INK      = 0x111111;
const PINK     = 0xF9D5D8, PINK_HI = 0xF4A9AF;
const BLUE     = 0xBFE4F4, BLUE_HI = 0x7CC7E8;
const GREY     = 0xdddddd;
const SERIF    = 'Georgia, "Times New Roman", serif';

const ROOT = new THREE.Group();
scene.add(ROOT);

// Pipeline axis: world direction that projects to exact screen-horizontal
// under the standard isometric pose (azimuth 45°, elevation 35.26°).
const AX = new THREE.Vector3(1, 0, -1).normalize();
function P(u, v) { return new THREE.Vector3(AX.x * u, v, AX.z * u); }

/* ── registry for highlight states ───────────────────────────────────────── */
const items = [];
function makeEntry(kind, stage, chan) {
  const e = { kind, stage, chan: (chan === undefined ? null : chan), mats: [], inks: [], labels: [], inkOp: 1 };
  items.push(e);
  return e;
}

/* ── primitives ──────────────────────────────────────────────────────────── */
function inkMaterial() {
  return new THREE.MeshBasicMaterial({ color: INK, transparent: true, opacity: 1 });
}

function segV(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) return null;
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8), mat || inkMaterial());
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  ROOT.add(m);
  return m;
}
function seg(e, u1, v1, u2, v2, r = 0.030) {
  const m = segV(P(u1, v1), P(u2, v2), r);
  if (e) e.inks.push(m.material);
  return m;
}

function curveTube(e, curve, r = 0.035) {
  const m = new THREE.Mesh(new THREE.TubeGeometry(curve, 160, r, 6, false), inkMaterial());
  ROOT.add(m);
  if (e) e.inks.push(m.material);
  return m;
}

function dashedCurve(e, curve, r = 0.033) {
  const mat = inkMaterial();
  const L = curve.getLength();
  const n = Math.max(3, Math.round(L / 0.34));
  for (let i = 0; i < n; i++) {
    const t0 = i / n, t1 = Math.min(1, t0 + 0.58 / n);
    segV(curve.getPointAt(t0), curve.getPointAt(t1), r, mat);
  }
  if (e) e.inks.push(mat);
  return mat;
}

function arrow(e, u1, u2, v, r = 0.042) {
  const mat = inkMaterial();
  segV(P(u1, v), P(u2 - 0.26, v), r, mat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.135, 0.32, 18), mat);
  cone.position.copy(P(u2 - 0.16, v));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), AX);
  ROOT.add(cone);
  if (e) e.inks.push(mat);
}

function dots(e, u, v, spacing = 0.30, r = 0.085) {
  const mat = inkMaterial();
  for (let i = -1; i <= 1; i++) {
    const s = new THREE.Mesh(new THREE.SphereGeometry(r, 12, 10), mat);
    s.position.copy(P(u + i * spacing, v));
    ROOT.add(s);
  }
  if (e) e.inks.push(mat);
}

function bracket(e, u, v0, v1, gapHalf = 0.75) {
  const vm = (v0 + v1) / 2;
  seg(e, u - 0.17, v0, u + 0.17, v0);
  seg(e, u - 0.17, v1, u + 0.17, v1);
  seg(e, u, v0, u, vm - gapHalf);
  seg(e, u, vm + gapHalf, u, v1);
}

function brace(e, u0, u1, v) {
  const mid = (u0 + u1) / 2, w = u1 - u0;
  const pts = [
    [u0, v - 0.30], [u0 + w * 0.08, v - 0.04], [u0 + w * 0.28, v + 0.01],
    [mid - w * 0.06, v + 0.03], [mid, v + 0.28], [mid + w * 0.06, v + 0.03],
    [u1 - w * 0.28, v + 0.01], [u1 - w * 0.08, v - 0.04], [u1, v - 0.30]
  ].map(p => P(p[0], p[1]));
  return curveTube(e, new THREE.CatmullRomCurve3(pts), 0.035);
}

function sheet(e, u, y, size, thick, kind, info) {
  const base = kind === 'act' ? PINK : BLUE;
  const hi = kind === 'act' ? PINK_HI : BLUE_HI;
  const g = new THREE.BoxGeometry(size, thick, size);
  const mat = new THREE.MeshBasicMaterial({ color: base, transparent: true, opacity: 1 });
  const mesh = new THREE.Mesh(g, mat);
  const em = new THREE.LineBasicMaterial({ color: INK, transparent: true, opacity: 1 });
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(g), em);
  const grp = new THREE.Group();
  grp.add(mesh, edges);
  grp.position.copy(P(u, y));
  ROOT.add(grp);
  e.mats.push({ m: mat, base, hi, tc: new THREE.Color(base), to: 1 });
  e.inks.push(em);
  if (info) registerInteractive(grp, info);
  return grp;
}

