  <button id="demoPrev">◀ Prev</button>
  <button id="demoNext">Next ▶</button>
</div>
<div id="demoTitle" style="font-weight:700;margin-top:2px;">1. RGB input</div>
<div id="demoText" style="line-height:1.4;">The input is a W×H image with 3 channels — three large pink sheets labelled R, G, B.</div>

<div style="border-top:1px solid #dcdfe3;margin-top:6px;padding-top:6px;color:#555;line-height:1.4;">
  Drag to orbit: the stacks are real 3D tensors — “channels” is a depth axis perpendicular to the W×H image plane.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
   input sheet (×3)      → BoxGeometry(3.2,0.06,3.2)  pink  + EdgesGeometry black
   layer1 map (×5)       → BoxGeometry(1.8,0.06,1.8)  pink  + edges
   logit diamond (×9)    → BoxGeometry(0.4,0.05,0.4)  pink  + edges
   layer1 filter (5×3)   → BoxGeometry(0.8,0.05,0.8)  blue  + edges
   layer2 filter (2×5)   → BoxGeometry(0.8,0.05,0.8)  blue  + edges
   arrow shaft           → CylinderGeometry r=0.045   black
   arrow head            → ConeGeometry(0.13,0.30)    black
   title rule / caption  → CylinderGeometry r=0.030   black
   channel bracket       → 4 × CylinderGeometry r=0.030 (serifs + broken stem)
   curly brace           → TubeGeometry on CatmullRomCurve3  r=0.035
   dashed leader         → dashed chain of CylinderGeometry on QuadraticBezierCurve3
   ellipsis dot          → SphereGeometry(0.085)      black
   all text              → addLabel() HTML overlay, serif (monospace for 'heron')
   ────────────────────────────────────────────────────────────────────────── */

const INK      = 0x111111;
const PINK     = 0xF9D5D8, PINK_HI = 0xF4A9AF;
const BLUE     = 0xBFE4F4, BLUE_HI = 0x7CC7E8;
const GREY     = 0xdddddd;
const SERIF    = 'Georgia, "Times New Roman", serif';

const ROOT = new THREE.Group();
scene.add(ROOT);

// Pipeline axis: world direction that projects to exact screen-horizontal
// under the standard isometric pose (azimuth 45°, elevation 35.26°).
const AX = new THREE.Vector3(1, 0, -1).normalize();
function P(u, v) { return new THREE.Vector3(AX.x * u, v, AX.z * u); }

/* ── registry for highlight states ───────────────────────────────────────── */
const items = [];
function makeEntry(kind, stage, chan) {
  const e = { kind, stage, chan: (chan === undefined ? null : chan), mats: [], inks: [], labels: [], inkOp: 1 };
  items.push(e);
  return e;
}

/* ── primitives ──────────────────────────────────────────────────────────── */
function inkMaterial() {
  return new THREE.MeshBasicMaterial({ color: INK, transparent: true, opacity: 1 });
}

function segV(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) return null;
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8), mat || inkMaterial());
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  ROOT.add(m);
  return m;
}
function seg(e, u1, v1, u2, v2, r = 0.030) {
  const m = segV(P(u1, v1), P(u2, v2), r);
  if (e) e.inks.push(m.material);
  return m;
}

function curveTube(e, curve, r = 0.035) {
  const m = new THREE.Mesh(new THREE.TubeGeometry(curve, 160, r, 6, false), inkMaterial());
  ROOT.add(m);
  if (e) e.inks.push(m.material);
  return m;
}

function dashedCurve(e, curve, r = 0.033) {
  const mat = inkMaterial();
  const L = curve.getLength();
  const n = Math.max(3, Math.round(L / 0.34));
  for (let i = 0; i < n; i++) {
    const t0 = i / n, t1 = Math.min(1, t0 + 0.58 / n);
    segV(curve.getPointAt(t0), curve.getPointAt(t1), r, mat);
  }
  if (e) e.inks.push(mat);
  return mat;
}

function arrow(e, u1, u2, v, r = 0.042) {
  const mat = inkMaterial();
  segV(P(u1, v), P(u2 - 0.26, v), r, mat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.135, 0.32, 18), mat);
  cone.position.copy(P(u2 - 0.16, v));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), AX);
  ROOT.add(cone);
  if (e) e.inks.push(mat);
}

function dots(e, u, v, spacing = 0.30, r = 0.085) {
  const mat = inkMaterial();
  for (let i = -1; i <= 1; i++) {
    const s = new THREE.Mesh(new THREE.SphereGeometry(r, 12, 10), mat);
    s.position.copy(P(u + i * spacing, v));
    ROOT.add(s);
  }
  if (e) e.inks.push(mat);
}

function bracket(e, u, v0, v1, gapHalf = 0.75) {
  const vm = (v0 + v1) / 2;
  seg(e, u - 0.17, v0, u + 0.17, v0);
  seg(e, u - 0.17, v1, u + 0.17, v1);
  seg(e, u, v0, u, vm - gapHalf);
  seg(e, u, vm + gapHalf, u, v1);
}

function brace(e, u0, u1, v) {
  const mid = (u0 + u1) / 2, w = u1 - u0;
  const pts = [
    [u0, v - 0.30], [u0 + w * 0.08, v - 0.04], [u0 + w * 0.28, v + 0.01],
    [mid - w * 0.06, v + 0.03], [mid, v + 0.28], [mid + w * 0.06, v + 0.03],
    [u1 - w * 0.28, v + 0.01], [u1 - w * 0.08, v - 0.04], [u1, v - 0.30]
  ].map(p => P(p[0], p[1]));
  return curveTube(e, new THREE.CatmullRomCurve3(pts), 0.035);
}

function sheet(e, u, y, size, thick, kind, info) {
  const base = kind === 'act' ? PINK : BLUE;
  const hi = kind === 'act' ? PINK_HI : BLUE_HI;
  const g = new THREE.BoxGeometry(size, thick, size);
  const mat = new THREE.MeshBasicMaterial({ color: base, transparent: true, opacity: 1 });
  const mesh = new THREE.Mesh(g, mat);
  const em = new THREE.LineBasicMaterial({ color: INK, transparent: true, opacity: 1 });
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(g), em);
  const grp = new THREE.Group();
  grp.add(mesh, edges);
  grp.position.copy(P(u, y));
  ROOT.add(grp);
  e.mats.push({ m: mat, base, hi, tc: new THREE.Color(base), to: 1 });
  e.inks.push(em);
  if (info) registerInteractive(grp, info);
  return grp;
}

function lab(e, text, pos, opts = {}) {
  const l = addLabel(text, pos, opts);
  l.div.style.fontFamily = opts.mono ? 'ui-monospace, Consolas, monospace' : SERIF;
  l.div.style.transition = 'opacity .16s linear';
  if (e) e.labels.push(l.div);
  return l;
}
function labU(e, text, u, v, opts) { return lab(e, text, P(u, v), opts); }
function rot90(t) { return '<span style="display:inline-block;transform:rotate(-90deg)">' + t + '</span>'; }

/* ── STAGE 0 : INPUT ─────────────────────────────────────────────────────── */
const eInput = makeEntry('act', 0);
const IN_U = -8.5, IN_S = 3.2, IN_H = IN_S / 2;
const inYs = [2.2, 1.6, 1.0];               // top .. bottom  (R, G, B)
const inNames = ['R', 'G', 'B'];
inYs.forEach((y, i) => {
  const g = sheet(eInput, IN_U, y, IN_S, 0.06, 'act', {
    title: 'Input channel ' + inNames[i],
    tooltip: 'Input ' + inNames[i] + ' channel (W×H)',
    body: 'The input tensor is W×H×3: one W×H sheet per colour channel. Stacked along the depth (channel) axis.'
  });
  lab(eInput, inNames[i], g.position.clone().add(new THREE.Vector3(-IN_H, 0, IN_H)), { offset: [-15, 0], fontSize: '14px' });
});
{
  const bc = P(IN_U, inYs[2]);
  lab(eInput, 'W', bc.clone().add(new THREE.Vector3(0, 0, IN_H)), { offset: [-14, 20], fontSize: '14px' });
  lab(eInput, 'H', bc.clone().add(new THREE.Vector3(IN_H, 0, 0)), { offset: [16, 20], fontSize: '14px' });
}
labU(eInput, 'Input', IN_U, 4.45, { fontSize: '16px' });
seg(eInput, IN_U - 2.2, 4.1, IN_U + 2.2, 4.1);
bracket(eInput, -5.6, -0.50, 3.70, 0.85);
labU(eInput, rot90('3 channels'), -5.6, 1.60, { fontSize: '13px' });

/* ── arrow 1 ─────────────────────────────────────────────────────────────── */
const eArrow1 = makeEntry('ink', 1);
arrow(eArrow1, -5.0, -2.3, 1.5);

/* ── STAGE 1 : LAYER 1 FEATURE MAPS ──────────────────────────────────────── */
const L1_U = -1.0, L1_S = 1.8, L1_H = L1_S / 2;
const l1Ys = [0.5, 1.05, 1.6, 2.15, 2.7];   // bottom .. top = channel 1..5
const eL1Deco = makeEntry('act', 1);
for (let i = 0; i < 5; i++) {
  const e = makeEntry('act', 1, i);
  sheet(e, L1_U, l1Ys[i], L1_S, 0.06, 'act', {
    title: 'Layer 1 feature map ' + (i + 1),
    tooltip: 'Feature map channel ' + (i + 1) + ' (W/2 × H/2)',
    body: 'Output channel ' + (i + 1) + ' of layer 1. It is produced by convolving the whole 3-channel input with filter group ' + (i + 1) + ' (three 3×3 filters) and summing the results.'
  });
}
{
  const bc = P(L1_U, l1Ys[0]);
  lab(eL1Deco, 'W/2', bc.clone().add(new THREE.Vector3(0, 0, L1_H)), { offset: [-18, 18], fontSize: '14px' });
  lab(eL1Deco, 'H/2', bc.clone().add(new THREE.Vector3(L1_H, 0, 0)), { offset: [20, 18], fontSize: '14px' });
}
labU(eL1Deco, 'Layer 1 feature maps', L1_U, 4.45, { fontSize: '16px' });
seg(eL1Deco, L1_U - 2.6, 4.1, L1_U + 2.6, 4.1);
bracket(eL1Deco, 1.1, 0.00, 3.15, 0.80);
labU(eL1Deco, rot90('5 channels'), 1.1, 1.575, { fontSize: '13px' });

/* ── arrows 2 & 3 + main ellipsis ────────────────────────────────────────── */
const eArrow2 = makeEntry('ink', 2);
arrow(eArrow2, 1.6, 3.4, 1.5);
dots(eArrow2, 4.2, 1.5, 0.32);
arrow(eArrow2, 4.9, 6.6, 1.5);

/* ── STAGE 2 : LOGITS ────────────────────────────────────────────────────── */
const eLogits = makeEntry('act', 2);
const LG_U = 7.2;
const lgYs = [];
for (let i = 0; i < 9; i++) lgYs.push(1.6 + (i - 4) * 0.42);
lgYs.forEach((y, i) => {
  sheet(eLogits, LG_U, y, 0.4, 0.05, 'act', {
    title: 'Logit ' + (i + 1),
    tooltip: 'Logit for class ' + (i + 1),
    body: 'After all layers the tensor is 1×1 with K channels — one unnormalised score per class.'
  });
});
{
  const bc = P(LG_U, lgYs[0]);
  lab(eLogits, '1', bc.clone().add(new THREE.Vector3(0, 0, 0.2)), { offset: [-9, 14], fontSize: '13px' });
  lab(eLogits, '1', bc.clone().add(new THREE.Vector3(0.2, 0, 0)), { offset: [10, 14], fontSize: '13px' });
}
labU(eLogits, 'Logits', LG_U, 4.45, { fontSize: '16px' });
seg(eLogits, LG_U - 0.85, 4.1, LG_U + 0.85, 4.1);
bracket(eLogits, 8.1, -0.28, 3.48, 0.80);
labU(eLogits, rot90('K channels'), 8.1, 1.60, { fontSize: '13px' });

/* ── STAGE 3 : argmax → heron ────────────────────────────────────────────── */
const eOut = makeEntry('ink', 3);
arrow(eOut, 8.7, 10.0, 1.5);
labU(eOut, 'heron', 10.95, 1.5, { fontSize: '17px', mono: true });
dashedCurve(eOut, new THREE.QuadraticBezierCurve3(P(9.30, 1.32), P(9.42, 0.92), P(9.95, 0.70)));
labU(eOut, 'argmax', 10.45, 0.42, { fontSize: '13px' });

/* ── LAYER 1 FILTERS ─────────────────────────────────────────────────────── */
const F_S = 0.8, F_H = F_S / 2;
const l1FilterU = [-9.2, -7.2, -5.2, -3.2, -1.2];
const l1Fys = [-4.55, -4.2, -3.85];         // bottom .. top  (B, G, R)
const eL1FDeco = makeEntry('filt', 1);
l1FilterU.forEach((u, gi) => {
  const e = makeEntry('filt', 1, gi);
  l1Fys.forEach((y, si) => {
    const g = sheet(e, u, y, F_S, 0.05, 'filt', {
      title: 'Layer 1 filter — group ' + (gi + 1) + ', channel ' + ['B', 'G', 'R'][si],
      tooltip: 'Filter group ' + (gi + 1) + ', ' + ['B', 'G', 'R'][si] + ' slice (3×3)',
      body: 'Each layer-1 filter group has one 3×3 filter per INPUT channel (3 of them). Convolving all three with R, G, B and summing gives exactly one pink output feature map.'
    });
    if (gi === 0) {
      lab(e, ['B', 'G', 'R'][si], g.position.clone().add(new THREE.Vector3(-F_H, 0, F_H)), { offset: [-14, 0], fontSize: '14px' });
      if (si === 0) {
        lab(e, '3', g.position.clone().add(new THREE.Vector3(0, 0, F_H)), { offset: [-10, 15], fontSize: '13px' });
        lab(e, '3', g.position.clone().add(new THREE.Vector3(F_H, 0, 0)), { offset: [11, 15], fontSize: '13px' });
      }
    }
  });
});
brace(eL1FDeco, -9.9, -0.5, -2.90);
dashedCurve(eL1FDeco, new THREE.QuadraticBezierCurve3(P(-5.20, -2.55), P(-4.05, -1.00), P(-3.65, 1.30)));
seg(eL1FDeco, -9.9, -5.75, -0.5, -5.75);
labU(eL1FDeco, 'layer 1 filters', -5.2, -6.15, { fontSize: '16px' });

/* ── LAYER 2 FILTERS ─────────────────────────────────────────────────────── */
const eL2FDeco = makeEntry('filt', 2);
const l2FilterU = [2.2, 5.6];
const l2Fys = [-4.7, -4.35, -4.0, -3.65, -3.3];
l2FilterU.forEach((u, gi) => {
  const e = makeEntry('filt', 2, null);
  l2Fys.forEach((y, si) => {
    const g = sheet(e, u, y, F_S, 0.05, 'filt', {
      title: 'Layer 2 filter group',
      tooltip: 'Layer 2 filter group (5 slices of 3×3)',
      body: 'A layer-2 filter group has one 3×3 filter per layer-1 channel — five of them, matching the 5 pink feature maps upstream.'
    });
    if (gi === 0 && si === 0) {
      lab(e, '3', g.position.clone().add(new THREE.Vector3(0, 0, F_H)), { offset: [-10, 15], fontSize: '13px' });
      lab(e, '3', g.position.clone().add(new THREE.Vector3(F_H, 0, 0)), { offset: [11, 15], fontSize: '13px' });
    }
  });
});
dots(eL2FDeco, 3.9, -4.0, 0.28, 0.075);
brace(eL2FDeco, 1.4, 6.4, -2.50);
dashedCurve(eL2FDeco, new THREE.QuadraticBezierCurve3(P(3.90, -2.15), P(2.85, -1.00), P(2.50, 1.30)));
seg(eL2FDeco, 1.4, -5.75, 6.4, -5.75);
labU(eL2FDeco, 'layer 2 filters', 3.9, -6.15, { fontSize: '16px' });

/* ── invisible padding so overlay text is not clipped by the auto-fit ────── */
[[-11.4, 1.5], [12.6, 1.5], [0, 4.9], [0, -6.8]].forEach(p => {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(0.02, 4, 3),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
  );
  m.position.copy(P(p[0], p[1]));
  ROOT.add(m);
});

/* ── CAMERA (after all geometry) ─────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.68
});
document.getElementById('btnReset').style.display = '';

/* ── STATE + HIGHLIGHTING ────────────────────────────────────────────────── */
const STAGES = ['RGB input', 'Layer 1 feature maps', 'Logits', 'argmax → heron'];
const state = { stage: 0, chan: 1, role: 'both' };

function applyState() {
  for (const e of items) {
    let lvl = e.stage < state.stage ? 1 : (e.stage === state.stage ? 2 : 0);
    if (e.kind === 'act' && state.role === 'filt') lvl = 0;
    if (e.kind === 'filt' && state.role === 'act') lvl = 0;
    if (e.chan !== null && lvl > 0) lvl = (e.chan === state.chan - 1) ? 2 : 1;
    e.inkOp = (lvl === 0) ? 0.16 : 1;
    for (const mm of e.mats) {
      mm.tc.set(lvl === 2 ? mm.hi : (lvl === 1 ? mm.base : GREY));
      mm.to = (lvl === 0) ? 0.24 : 1;
    }
    for (const d of e.labels) d.style.opacity = (lvl === 0) ? '0.20' : '1';
  }
}

(function tween() {
  requestAnimationFrame(tween);
  for (const e of items) {
    for (const mm of e.mats) {
      mm.m.color.lerp(mm.tc, 0.18);
      mm.m.opacity += (mm.to - mm.m.opacity) * 0.18;
    }
    for (const im of e.inks) im.opacity += (e.inkOp - im.opacity) * 0.18;
  }
})();

/* ── UI WIRING ───────────────────────────────────────────────────────────── */
const btnStage = document.getElementById('btnStage');
const chSel = document.getElementById('chSel');
const chOut = document.getElementById('chOut');
const roleBtns = {
  act: document.getElementById('roleAct'),
  filt: document.getElementById('roleFilt'),
  both: document.getElementById('roleBoth')
};

function syncUI() {
  btnStage.textContent = 'Stage ' + (state.stage + 1) + '/4 — ' + STAGES[state.stage];
  chSel.value = String(state.chan);
  chOut.textContent = String(state.chan);
  for (const k in roleBtns) roleBtns[k].classList.toggle('active', state.role === k);
}

btnStage.addEventListener('click', () => {
  state.stage = (state.stage + 1) % 4;
  syncUI(); applyState();
});
chSel.addEventListener('input', () => {
  state.chan = parseInt(chSel.value, 10);
  syncUI(); applyState();
});
for (const k in roleBtns) {
  roleBtns[k].addEventListener('click', () => {
    state.role = k;
    syncUI(); applyState();
  });
}

/* ── GUIDED DEMO ─────────────────────────────────────────────────────────── */
const ROLE_MAP = { 'Activations (pink)': 'act', 'Filters (blue)': 'filt', 'Both': 'both' };
const STEPS = [
  { title: 'RGB input', narration: 'The input is a W×H image with 3 channels — three large pink sheets labelled R, G, B.', state: { pipelineStage: 'RGB input', tensorRole: 'Activations (pink)' } },
  { title: 'Layer 1 filters', narration: 'Five blue filter groups appear; each group holds three 3×3 filters, one for every input channel.', state: { pipelineStage: 'Layer 1 feature maps', tensorRole: 'Filters (blue)', channelSelect: 1 } },
  { title: 'One output channel', narration: 'Selecting channel 3 brightens one pink feature map and the single blue filter group that produced it.', state: { pipelineStage: 'Layer 1 feature maps', tensorRole: 'Both', channelSelect: 3 } },
  { title: 'Deeper: smaller and thicker', narration: 'Layer 1 feature maps are W/2 × H/2 but 5 channels deep — spatial size shrank while depth grew.', state: { pipelineStage: 'Layer 1 feature maps', tensorRole: 'Activations (pink)', channelSelect: 3 } },
  { title: 'Logits', narration: 'After more layers the tensor is 1×1 with K channels: a vertical column of tiny pink diamonds, one score per class.', state: { pipelineStage: 'Logits', tensorRole: 'Activations (pink)' } },
  { title: 'argmax', narration: "Taking the argmax over the K logits picks the winning class and prints 'heron'.", state: { pipelineStage: 'argmax → heron', tensorRole: 'Activations (pink)' } }
];
let stepIdx = 0;
const demoTitle = document.getElementById('demoTitle');
const demoText = document.getElementById('demoText');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  if (s.state.pipelineStage) state.stage = STAGES.indexOf(s.state.pipelineStage);
  if (s.state.tensorRole) state.role = ROLE_MAP[s.state.tensorRole];
  if (s.state.channelSelect) state.chan = s.state.channelSelect;
  demoTitle.textContent = (stepIdx + 1) + '. ' + s.title;
  demoText.textContent = s.narration;
  syncUI(); applyState();
}
document.getElementById('demoNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('demoPrev').addEventListener('click', () => goToStep(stepIdx - 1));

goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

