// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
   input sheet (×3)      → BoxGeometry(3.2,0.06,3.2)  pink #F9D5D8 + black rim + edges
   layer1 map (×5)       → BoxGeometry(1.8,0.06,1.8)  pink  + rim + edges
   logit diamond (×9)    → BoxGeometry(0.38,0.05,0.38) pink + rim + edges
   layer1 filter (5×3)   → BoxGeometry(0.8,0.05,0.8)  blue #BFE4F4 + rim + edges
   layer2 filter (2×5)   → BoxGeometry(0.8,0.05,0.8)  blue  + rim + edges
   arrow shaft           → CylinderGeometry r=0.042   black
   arrow head            → ConeGeometry(0.135,0.32)   black
   title rule / caption  → CylinderGeometry r=0.030   black
   channel bracket       → 4 × CylinderGeometry r=0.030 (serifs + broken stem)
   curly brace           → 2 mirrored TubeGeometry halves meeting in a cusp,
                           with downward tails at both ends
   dashed leader         → dashed chain of CylinderGeometry on QuadraticBezierCurve3
   ellipsis dot          → SphereGeometry(0.085)      black
   all text              → addLabel() HTML overlay, serif (monospace for 'heron')
   ────────────────────────────────────────────────────────────────────────── */

const INK = 0x111111;
const PINK = 0xF9D5D8, PINK_HI = 0xF4A9AF;
const BLUE = 0xBFE4F4, BLUE_HI = 0x7CC7E8;
const WHITE = new THREE.Color(0xffffff);
const SERIF = 'Georgia, "Times New Roman", serif';

// Authored in "figure units" then uniformly scaled into world space.
const SC = 0.36;
const ROOT = new THREE.Group();
ROOT.scale.setScalar(SC);
scene.add(ROOT);

// Pipeline axis: world direction that projects to exact screen-horizontal
// under the standard isometric pose (azimuth 45°, elevation 35.26°).
const AX = new THREE.Vector3(1, 0, -1).normalize();
function P(u, v) { return new THREE.Vector3(AX.x * u, v, AX.z * u); }

// Points used for the custom (tight) camera fit — figure-space coordinates.
const fitPts = [];

/* ── registry for highlight states ───────────────────────────────────────── */
const items = [];
function makeEntry(kind, stage, chan) {
  const e = { kind, stage, chan: (chan === undefined ? null : chan), mats: [], inks: [], labels: [], inkOp: 1 };
  items.push(e);
  return e;
}

/* ── primitives ──────────────────────────────────────────────────────────── */
function inkMaterial() {
  return new THREE.MeshBasicMaterial({ color: INK, transparent: true, opacity: 1 });
}

function segV(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) return null;
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8), mat || inkMaterial());
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  ROOT.add(m);
  return m;
}
function seg(e, u1, v1, u2, v2, r = 0.030) {
  const m = segV(P(u1, v1), P(u2, v2), r);
  if (e && m) e.inks.push(m.material);
  fitPts.push(P(u1, v1), P(u2, v2));
  return m;
}

function curveTube(e, curve, r = 0.034) {
  const m = new THREE.Mesh(new THREE.TubeGeometry(curve, 160, r, 6, false), inkMaterial());
  ROOT.add(m);
  if (e) e.inks.push(m.material);
  return m;
}

function dashedCurve(e, curve, r = 0.033) {
  const mat = inkMaterial();
  const L = curve.getLength();
  const n = Math.max(3, Math.round(L / 0.34));
  for (let i = 0; i < n; i++) {
    const t0 = i / n, t1 = Math.min(1, t0 + 0.58 / n);
    segV(curve.getPointAt(t0), curve.getPointAt(t1), r, mat);
  }
  if (e) e.inks.push(mat);
  return mat;
}

function arrow(e, u1, u2, v, r = 0.042) {
  const mat = inkMaterial();
  segV(P(u1, v), P(u2 - 0.26, v), r, mat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.135, 0.32, 18), mat);
  cone.position.copy(P(u2 - 0.16, v));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), AX);
  ROOT.add(cone);
  if (e) e.inks.push(mat);
  fitPts.push(P(u1, v), P(u2, v));
}

function dots(e, u, v, spacing = 0.32, r = 0.085) {
  const mat = inkMaterial();
  for (let i = -1; i <= 1; i++) {
    const s = new THREE.Mesh(new THREE.SphereGeometry(r, 12, 10), mat);
    s.position.copy(P(u + i * spacing, v));
    ROOT.add(s);
  }
  if (e) e.inks.push(mat);
}

function bracket(e, u, v0, v1, gapHalf, serif = 0.19) {
  const vm = (v0 + v1) / 2;
  seg(e, u - serif, v0, u + serif, v0);
  seg(e, u - serif, v1, u + serif, v1);
  seg(e, u, v0, u, vm - gapHalf);
  seg(e, u, vm + gapHalf, u, v1);
}

// Curly brace: two mirrored halves that MEET IN A CUSP at the apex, each ending
// in a downward tail — matching the printed brace profile.
function brace(e, u0, u1, v) {
  const mid = (u0 + u1) / 2, w = u1 - u0;
  const half = (uEnd, s) => {
    const pts = [
      [uEnd, v - 0.36],
      [uEnd + s * 0.03, v - 0.20],
      [uEnd + s * 0.12, v - 0.03],
      [uEnd + s * w * 0.10, v + 0.005],
      [mid - s * w * 0.16, v + 0.025],
      [mid - s * 0.20, v + 0.06],
      [mid - s * 0.05, v + 0.22],
      [mid, v + 0.38]
    ].map(p => P(p[0], p[1]));
    curveTube(e, new THREE.CatmullRomCurve3(pts), 0.032);
  };
  half(u0, +1);
  half(u1, -1);
  fitPts.push(P(u0, v - 0.4), P(u1, v - 0.4), P(mid, v + 0.4));
}

// A thin coloured slab with a slightly larger, thinner black slab beneath it:
// the black rim reads as a constant ~2px ink outline from any zoom.
function sheet(e, u, y, size, thick, kind, info) {
  const base = kind === 'act' ? PINK : BLUE;
  const hi = kind === 'act' ? PINK_HI : BLUE_HI;
  const rim = Math.min(0.055, size * 0.09);

  const grp = new THREE.Group();
  grp.position.copy(P(u, y));

  const rimGeo = new THREE.BoxGeometry(size + 2 * rim, thick * 0.5, size + 2 * rim);
  const rimMat = new THREE.MeshBasicMaterial({ color: INK, transparent: true, opacity: 1 });
  const rimMesh = new THREE.Mesh(rimGeo, rimMat);
  rimMesh.renderOrder = 0;

  const geo = new THREE.BoxGeometry(size, thick, size);
  const mat = new THREE.MeshBasicMaterial({ color: base, transparent: true, opacity: 1 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.renderOrder = 1;

  const em = new THREE.LineBasicMaterial({ color: INK, transparent: true, opacity: 1 });
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(rimGeo), em);
  edges.renderOrder = 2;

  grp.add(rimMesh, mesh, edges);
  ROOT.add(grp);

  const h = size / 2;
  for (const dx of [-h, h]) for (const dz of [-h, h]) {
    fitPts.push(new THREE.Vector3(grp.position.x + dx, grp.position.y, grp.position.z + dz));
  }

  e.mats.push({ m: mat, base: new THREE.Color(base), hi: new THREE.Color(hi), tc: new THREE.Color(base) });
  e.inks.push(rimMat, em);
  if (info) registerInteractive(grp, info);
  return grp;
}

function lab(e, text, figPos, opts = {}) {
  const l = addLabel(text, figPos.clone().multiplyScalar(SC), opts);
  l.div.style.fontFamily = opts.mono ? 'ui-monospace, Consolas, monospace' : SERIF;
  l.div.style.transition = 'opacity .16s linear';
  if (e) e.labels.push(l.div);
  return l;
}
function labU(e, text, u, v, opts) { return lab(e, text, P(u, v), opts); }
function rot90(t) {
  return '<span style="display:inline-block;transform:rotate(-90deg);background:#fff;padding:0 5px;">' + t + '</span>';
}

/* ── STAGE 0 : INPUT ─────────────────────────────────────────────────────── */
const eInput = makeEntry('act', 0);
const IN_U = -8.5, IN_S = 3.2, IN_H = IN_S / 2;
const inYs = [2.2, 1.6, 1.0];               // top .. bottom  (R, G, B)  spacing 0.6
const inNames = ['R', 'G', 'B'];
inYs.forEach((y, i) => {
  const g = sheet(eInput, IN_U, y, IN_S, 0.06, 'act', {
    title: 'Input channel ' + inNames[i],
    tooltip: 'Input ' + inNames[i] + ' channel (W×H)',
    body: 'The input tensor is W×H×3: one W×H sheet per colour channel, stacked along the depth (channel) axis.'
  });
  lab(eInput, inNames[i], g.position.clone().add(new THREE.Vector3(-IN_H, 0, IN_H)),
    { offset: [-19, 0], fontSize: '16px' });
});
{
  const bc = P(IN_U, inYs[2]);
  lab(eInput, 'W', bc.clone().add(new THREE.Vector3(0, 0, IN_H)), { offset: [-20, 24], fontSize: '16px' });
  lab(eInput, 'H', bc.clone().add(new THREE.Vector3(IN_H, 0, 0)), { offset: [22, 24], fontSize: '16px' });
}
labU(eInput, 'Input', IN_U, 4.48, { fontSize: '19px' });
seg(eInput, IN_U - 2.3, 4.05, IN_U + 2.3, 4.05);
bracket(eInput, -5.6, -0.6, 3.8, 1.25);
labU(eInput, rot90('3 channels'), -5.6, 1.60, { fontSize: '15px' });

/* ── arrow 1 ─────────────────────────────────────────────────────────────── */
const eArrow1 = makeEntry('ink', 1);
arrow(eArrow1, -5.0, -2.3, 1.5);

/* ── STAGE 1 : LAYER 1 FEATURE MAPS ──────────────────────────────────────── */
const L1_U = -1.0, L1_S = 1.8, L1_H = L1_S / 2;
const l1Ys = [0.50, 1.05, 1.60, 2.15, 2.70];   // bottom .. top = channel 1..5
const eL1Deco = makeEntry('act', 1);
for (let i = 0; i < 5; i++) {
  const e = makeEntry('act', 1, i);
  sheet(e, L1_U, l1Ys[i], L1_S, 0.06, 'act', {
    title: 'Layer 1 feature map ' + (i + 1),
    tooltip: 'Feature map channel ' + (i + 1) + ' (W/2 × H/2)',
    body: 'Output channel ' + (i + 1) + ' of layer 1. It is produced by convolving the whole 3-channel input with filter group ' + (i + 1) + ' (three 3×3 filters) and summing the results.'
  });
}
{
  const bc = P(L1_U, l1Ys[0]);
  lab(eL1Deco, 'W/2', bc.clone().add(new THREE.Vector3(0, 0, L1_H)), { offset: [-26, 22], fontSize: '16px' });
  lab(eL1Deco, 'H/2', bc.clone().add(new THREE.Vector3(L1_H, 0, 0)), { offset: [28, 22], fontSize: '16px' });
}
labU(eL1Deco, 'Layer 1 feature maps', L1_U, 4.48, { fontSize: '19px' });
seg(eL1Deco, L1_U - 2.8, 4.05, L1_U + 2.8, 4.05);
bracket(eL1Deco, 1.1, -0.5, 3.7, 1.25);
labU(eL1Deco, rot90('5 channels'), 1.1, 1.60, { fontSize: '15px' });

/* ── arrows 2 & 3 + main ellipsis ────────────────────────────────────────── */
const eArrow2 = makeEntry('ink', 2);
arrow(eArrow2, 1.6, 3.4, 1.5);
dots(eArrow2, 4.2, 1.5, 0.34);
arrow(eArrow2, 4.9, 6.6, 1.5);

/* ── STAGE 2 : LOGITS ────────────────────────────────────────────────────── */
const eLogits = makeEntry('act', 2);
const LG_U = 7.2, LG_S = 0.38, LG_SP = 0.40;
const lgYs = [];
for (let i = 0; i < 9; i++) lgYs.push(1.6 + (i - 4) * LG_SP);
