/* ── CAMERA: pose from the standard isometric solve, then a TIGHT custom
      fit measured from the real figure points (a Box3 of this long diagonal
      layout badly over-estimates the drawn extent and shrinks the figure). ── */
const VIEW = { projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0 };
const FILL = 0.96;

function fitFigure() {
  setCameraView({ ...VIEW, heightFraction: 0.9 });      // establishes the pose
  camera.updateMatrixWorld();
  const inv = camera.matrixWorldInverse;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity, minZ = Infinity, maxZ = -Infinity;
  const t = new THREE.Vector3();
  for (const p of fitPts) {
    t.copy(p).multiplyScalar(SC).applyMatrix4(inv);
    minX = Math.min(minX, t.x); maxX = Math.max(maxX, t.x);
    minY = Math.min(minY, t.y); maxY = Math.max(maxY, t.y);
    minZ = Math.min(minZ, t.z); maxZ = Math.max(maxZ, t.z);
  }
  const w = Math.max(maxX - minX, 1e-4), h = Math.max(maxY - minY, 1e-4);
  const asp = Math.max(0.2, canvas.clientWidth / Math.max(1, canvas.clientHeight));
  const zoom = Math.min((2 * d * FILL) / h, (2 * d * asp * FILL) / w);
  const c = new THREE.Vector3((minX + maxX) / 2, (minY + maxY) / 2, (minZ + maxZ) / 2)
    .applyMatrix4(camera.matrixWorld);
  setCameraView({ ...VIEW, zoom, target: [c.x, c.y, c.z] });
}
fitFigure();
document.getElementById('btnReset').style.display = '';

let userMoved = false;
controls.addEventListener('start', () => { userMoved = true; });
document.getElementById('btnReset').addEventListener('click', () => { userMoved = false; fitFigure(); });
let _fitQueued = false;
new ResizeObserver(() => {
  if (userMoved || _fitQueued) return;
  _fitQueued = true;
  requestAnimationFrame(() => { _fitQueued = false; if (!userMoved) fitFigure(); });
}).observe(canvas);

/* ── STATE + HIGHLIGHTING ────────────────────────────────────────────────── */
const STAGES = ['Overview', 'RGB input', 'Layer 1 feature maps', 'Logits', 'argmax → heron'];
// Default = the printed figure: every sheet in its base pink/blue, no channel pick.
const state = { stage: 0, chan: 1, chanActive: false, role: 'both' };

function applyState() {
  const cur = state.stage - 1;              // -1 = overview: nothing is dimmed
  for (const e of items) {
    let lvl;
    if (cur < 0) lvl = 1;
    else lvl = e.stage < cur ? 1 : (e.stage === cur ? 2 : 0);
    if (e.kind === 'act' && state.role === 'filt') lvl = 0;
    if (e.kind === 'filt' && state.role === 'act') lvl = 0;
    if (state.chanActive && e.chan !== null && lvl > 0) lvl = (e.chan === state.chan - 1) ? 2 : 1;
    if (cur < 0 && !state.chanActive && state.role === 'both') lvl = 1;   // pristine figure

    // De-emphasis keeps the hue and the ink: it only washes the fill toward
    // white and thins the outline, so the whole diagram stays readable.
    e.inkOp = (lvl === 0) ? 0.40 : 1;
    for (const mm of e.mats) {
      if (lvl === 2) mm.tc.copy(mm.hi);
      else if (lvl === 1) mm.tc.copy(mm.base);
      else mm.tc.copy(mm.base).lerp(WHITE, 0.5);
    }
    for (const dv of e.labels) dv.style.opacity = (lvl === 0) ? '0.42' : '1';
  }
}

(function tween() {
  requestAnimationFrame(tween);
  for (const e of items) {
    for (const mm of e.mats) mm.m.color.lerp(mm.tc, 0.20);
    for (const im of e.inks) im.opacity += (e.inkOp - im.opacity) * 0.20;
  }
})();

