};

function syncUI() {
  btnStage.textContent = 'Stage ' + (state.stage + 1) + '/5 — ' + STAGES[state.stage];
  chSel.value = String(state.chan);
  chOut.textContent = state.chanActive ? String(state.chan) : '—';
  for (const k in roleBtns) roleBtns[k].classList.toggle('active', state.role === k);
}

btnStage.addEventListener('click', () => {
  state.stage = (state.stage + 1) % STAGES.length;
  if (state.stage === 0) { state.chanActive = false; state.role = 'both'; }  // back to the plain figure
  syncUI(); applyState();
});
chSel.addEventListener('input', () => {
  state.chan = parseInt(chSel.value, 10);
  state.chanActive = true;
  syncUI(); applyState();
});
for (const k in roleBtns) {
  roleBtns[k].addEventListener('click', () => {
    state.role = k;
    syncUI(); applyState();
  });
}

